import sys


def main():
    data = sys.stdin.read().split()
    n, q = int(data[0]), int(data[1])
    words = data[2:2 + n]
    prefixes = data[2 + n:2 + n + q]
    for p in prefixes:
        count = 0
        for w in words:
            if len(w) >= len(p) and w[:len(p)] == p:
                count += 1
        print(count)


main()
